sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float strength;
uniform float angle;
uniform float phase;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float style;
uniform float edgeStyle;
uniform float4 screen;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 lines(float2 coord, half4 src) {
    float period = size.x / max(amount, 0.5);
    float a = radians(angle);
    float2 n = float2(-sin(a), cos(a));
    float u = dot(coord - size * 0.5, n) / period + phase + 0.5;
    float d = fract(u) - 0.5;
    half4 c = image.eval(clamp(coord - d * period * n, screen.xy + 0.5, screen.xy + screen.zw - 0.5));
    float dark = clamp(float(c.a) - luma(float3(c.rgb)), 0.0, 1.0);
    float w = max(2.0 * (dark - strength), 0.0) * period * 0.5;
    float e = abs(d) * period;
    float soft = 0.111 * period;
    float line = smoothstep(-soft, soft, w - e) - smoothstep(-soft, soft, -w - e);
    float3 rgb = mix(float3(color2.rgb), float3(color1.rgb), line);
    return half4(half3(rgb) * src.a, src.a);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    if (edgeStyle > 0.5) return lines(coord, src);
    float period = size.x / max(amount, 0.5);
    float a = radians(angle);
    float u = dot(coord - size * 0.5, float2(-sin(a), cos(a))) / period + phase + (style > 0.5 ? 0.5 : 0.0);
    float s = clamp(strength, 0.001, 0.999);
    float dark = clamp(1.0 - luma(float3(src.rgb) / float(src.a)), 0.0, 1.0);
    float ink = style > 0.5 ? clamp(1.815 * dark - 1.757 * strength + 0.022, 0.0, 1.0) : pow(dark, (1.0 - s) / s);
    float e = abs(fract(u) - 0.5) * period;
    float line = clamp(ink * period * 0.5 - e + 0.5, 0.0, 1.0);
    float3 rgb = mix(float3(color2.rgb), float3(color1.rgb), line);
    return half4(half3(rgb) * src.a, src.a);
}
